package hk.overlander.journal;
import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.os.*;
import android.view.KeyEvent;
import android.widget.Toast;
import org.json.JSONArray;
import java.io.File;

public class MusicPlaybackService extends Service {
  private MediaPlayer player;private MediaSession session;private AudioManager audio;private boolean ready=false;private String current;
  private JSONArray playlist=new JSONArray();private int index=0;private int loop=1;private boolean rail=false;
  private final AudioManager.OnAudioFocusChangeListener focus=change->{if(change<=0)pause();};
  private final Handler progressHandler=new Handler(Looper.getMainLooper());
  private final Runnable progressRunnable=new Runnable(){public void run(){if(ready&&player!=null&&player.isPlaying()){Intent update=new Intent("hk.overlander.journal.PLAYBACK_PROGRESS");update.putExtra("position",player.getCurrentPosition());update.putExtra("duration",player.getDuration());sendBroadcast(update);progressHandler.postDelayed(this,1000);}}};
  @Override public void onCreate(){super.onCreate();audio=(AudioManager)getSystemService(AUDIO_SERVICE);if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("music","窗邊收音機",NotificationManager.IMPORTANCE_LOW));session=new MediaSession(this,"Overlander");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onStop(){stopSelf();}public void onSkipToNext(){next();}public void onSkipToPrevious(){previous();}public void onSeekTo(long pos){seek(pos);}public boolean onMediaButtonEvent(Intent i){KeyEvent e=i.getParcelableExtra(Intent.EXTRA_KEY_EVENT);if(e!=null&&e.getAction()==KeyEvent.ACTION_DOWN){int code=e.getKeyCode();if(code==KeyEvent.KEYCODE_MEDIA_PAUSE)pause();else if(code==KeyEvent.KEYCODE_MEDIA_STOP)stopSelf();else if(code==KeyEvent.KEYCODE_MEDIA_PLAY)play();else if(code==KeyEvent.KEYCODE_MEDIA_NEXT)next();else if(code==KeyEvent.KEYCODE_MEDIA_PREVIOUS)previous();else if(ready&&player.isPlaying())pause();else play();return true;}return super.onMediaButtonEvent(i);}});registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));}
  private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
  @Override public int onStartCommand(Intent i,int flags,int id){startForeground(2002,notification());if(i==null){stopSelf();return START_NOT_STICKY;}String a=i.getAction();SharedPreferences p=getSharedPreferences("journey",0);try{playlist=new JSONArray(p.getString("playlist","[]"));}catch(Exception e){playlist=new JSONArray();}index=p.getInt("playlistIndex",0);loop=p.getInt("loopMode",1);if("stop".equals(a)){stopSelf();return START_NOT_STICKY;}if("pause".equals(a)){pause();return START_NOT_STICKY;}if("next".equals(a)){next();return START_NOT_STICKY;}if("prev".equals(a)){previous();return START_NOT_STICKY;}if("loop".equals(a)){update();return START_NOT_STICKY;}if("seek".equals(a)){int target=i.getIntExtra("position",-1);if(ready&&player!=null&&target>=0)player.seekTo(target);update();return START_NOT_STICKY;}if("reload".equals(a)){if(playlist.length()>0){index=Math.min(index,playlist.length()-1);load(index);}else fail("播放清單未有音樂");return START_NOT_STICKY;}if("playRail".equals(a)){rail=true;String path=i.getStringExtra("path");if(path!=null)load(path);else fail("火車聲未能載入");return START_NOT_STICKY;}if(playlist.length()==0){fail("請先加入音樂");return START_NOT_STICKY;}if(index>=playlist.length())index=0;if("toggle".equals(a)&&ready&&player.isPlaying())pause();else load(index);return START_NOT_STICKY;}
  private void load(int i){rail=false;index=i;getSharedPreferences("journey",0).edit().putInt("playlistIndex",i).commit();load(playlist.optString(i));}
  private void load(String path){try{File f=new File(path);String root=getFilesDir().getCanonicalPath()+File.separator;if(!f.getCanonicalPath().startsWith(root)||!f.isFile())throw new Exception();if(player!=null)player.release();ready=false;current=path;player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setDataSource(path);player.setLooping(loop==2&&!rail);player.setOnPreparedListener(p->{ready=true;play();});player.setOnCompletionListener(p->{if(rail)return;if(loop==2){p.seekTo(0);p.start();}else if(loop==1&&playlist.length()>0){load((index+1)%playlist.length());}else{pause();}});player.setOnErrorListener((p,w,e)->{fail("音樂無法播放，請重新選擇");return true;});player.prepareAsync();String title=rail?"原創合成火車聲":(playlist.length()>0?(index+1)+" / "+playlist.length()+" · 窗邊音樂":"窗邊音樂");session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,"THE OVERLANDER").build());update();}catch(Exception e){fail("音樂檔案無法開啟");}}
  private void play(){if(!ready||player==null)return;if(audio.requestAudioFocus(focus,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){fail("未能取得音訊播放權");return;}try{startForeground(2002,notification());session.setActive(true);player.start();update();progressHandler.removeCallbacks(progressRunnable);progressHandler.postDelayed(progressRunnable,1000);}catch(Exception e){fail("播放失敗");}}
  private void pause(){if(ready&&player!=null&&player.isPlaying())player.pause();audio.abandonAudioFocus(focus);progressHandler.removeCallbacks(progressRunnable);update();stopForeground(false);}
  private void next(){if(playlist.length()==0)return;load((index+1)%playlist.length());}
  private void previous(){if(playlist.length()==0)return;load((index-1+playlist.length())%playlist.length());}
  private void seek(long pos){if(ready&&player!=null)player.seekTo((int)pos);update();}
  private PendingIntent action(String a,int request){return PendingIntent.getService(this,request,new Intent(this,MusicPlaybackService.class).setAction(a),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
  private Notification notification(){boolean playing=ready&&player!=null&&player.isPlaying();String label=rail?"原創合成火車聲":(playlist.length()>0?(index+1)+" / "+playlist.length()+" · 窗邊音樂":"窗邊音樂");Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"music"):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("漫遊日誌 · 窗邊收音機").setContentText(label+(playing?" · 播放中":" · 暫停")).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setVisibility(Notification.VISIBILITY_PUBLIC).setOnlyAlertOnce(true).setOngoing(playing).addAction(android.R.drawable.ic_media_previous,"上一首",action("prev",3)).addAction(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing?"暫停":"播放",action(playing?"pause":"play",1)).addAction(android.R.drawable.ic_media_next,"下一首",action("next",4)).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();}
  private void update(){boolean playing=ready&&player!=null&&player.isPlaying();long actions=PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO;session.setPlaybackState(new PlaybackState.Builder().setActions(actions).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,ready?player.getCurrentPosition():0,playing?1:0).build());((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(2002,notification());}
  private void fail(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();stopSelf();}
  @Override public void onDestroy(){unregisterReceiver(noisy);progressHandler.removeCallbacks(progressRunnable);if(player!=null)player.release();audio.abandonAudioFocus(focus);session.setActive(false);session.release();stopForeground(true);super.onDestroy();}
  @Override public IBinder onBind(Intent i){return null;}
}
